// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(address guesser, bytes32 guess) public {
        vm.assume(guesser != address(0) && guesser != address(this));
        vm.deal(guesser, 2 ether);

        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guess);

        // Try to settle in the same transaction
        vm.prank(guesser);
        try c.settle() {
            // If settle succeeds, the guesser got paid
            uint256 balanceAfter = address(c).balance;
            uint256 guesserBalance = guesser.balance;
            // Reference: settle should always fail or at least not guarantee payment when called in same tx.
            // Mutant: settle can succeed in same tx and pay out, draining the contract.
            // Rule: After a lockInGuess + settle in the SAME transaction, the contract balance
            // must not drop below 1 ether because the guesser cannot know the future block hash.
            // The mutant breaks this by using the current block hash, so the guesser can win.
            assertTrue(address(c).balance >= 1 ether, "Contract balance dropped below 1 ether in same tx");
        } catch {
            // settle reverted, which is fine for the reference (and mutant may not always succeed)
            assertTrue(true, "settle reverted as expected");
        }
    }
}

