pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 settleAfter) public {
        // settleAfter is the number of blocks to wait after lockInGuess before calling settle.
        // Admissible: settle must be called after the stored block (block+1 for correct, block+2 for bug).
        // We bound to a reasonable range; let the fuzzer explore various delays.
        vm.assume(settleAfter >= 1 && settleAfter <= 5);

        // Fund the test contract to deploy with 1 ether.
        vm.deal(address(this), 1 ether);
        c = new C{value: 1 ether}();

        // Fund actor and lock in guess.
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance blocks.
        vm.roll(block.number + settleAfter);

        // Now call settle. In the reference contract (lockInGuess stores block+1),
        // settleAfter >= 1 means block.number > stored block, so settle should succeed.
        // In the buggy contract (stores block+2), settleAfter=1 leaves block.number == stored block,
        // so the require(block.number > guesses[msg.sender].block) fails, causing a revert.
        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: for any admissible settleAfter, the reference never reverts;
        // the bug reverts for settleAfter = 1.
        assertTrue(ok);
    }
}

