import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, bytes32 hash) public {
        vm.assume(value <= 10 ether);
        vm.deal(address(this), value);
        try c.lockInGuess{value: value}(hash) {} catch {}
        uint256 numGuesses;
        // The only way the contract receives Ether is through lockInGuess and constructor.
        // Constructor sets balance to 1 ether. Each successful lockInGuess adds exactly 1 ether in reference.
        // So balance should equal 1 ether + (number of successful guesses) * 1 ether.
        // We cannot read the internal mapping count. But we can assert: balance >= 1 ether, and
        // if value != 1 ether the call reverts in reference, and balance stays 1 ether.
        // The bug accepts value == 0 ether without revert, so balance stays 1 ether as if no call happened.
        // However, the bug does NOT increment the guess count on a value mismatch; the balance invariant
        // "balance >= 1 ether" always holds. That's not enough.
        // We need a property that the bug violates. Let's try: after a SUCCESSFUL lockInGuess (doesn't revert),
        // the contract's balance must have increased by exactly 1 ether from its previous value.
        // We need to track balance before and after, which we cannot do in a purely read-only assertion.
        // Instead, we can assert: if lockInGuess did not revert, then msg.value was exactly 1 ether.
        // But the fuzzer already supplies msg.value, so that's just checking the input, not state.
        // The real difference is that in the bug, you can lock in without paying, so subsequent settle
        // will not have enough balance to pay 2 ether. But settle requires blockhash, non-constant.
        // We cannot easily test settle in a fuzz.
        // We can assert on the contract's balance right after lockInGuess.
        // Reference: balance = 1 ether + (number of times lockInGuess succeeded) * 1 ether.
        // Bug: balance = 1 ether + (number of times lockInGuess succeeded with value==0 ether) * 0 ether.
        // Since the fuzzer may call multiple times, we need to track successes.
        // But we can't rely on a counter inside the test. We must assert on c alone.
        // Therefore, we'll use a simpler property: after the first lockInGuess call (assuming setup balance 1 ether),
        // if the call succeeded (did not revert), then balance >= 2 ether.
        // In reference, succeed => value == 1 ether => balance becomes 2 ether.
        // In bug, succeed with value == 0 ether => balance stays 1 ether < 2 ether.
        // But what if a previous call already succeeded? Then balance might be >2 anyway. So we need to reset.
        // We can deploy a fresh C for each fuzz input. setUp() already does that, but fuzz runs multiple calls
        // on the same instance. We need to ensure only one lockInGuess call is made per test.
        // That's acceptable because the fuzzer will find the input that triggers the bug in one call.
        // So we do a single call and assert balance >= 2 ether if the call didn't revert.
        bool ok;
        try c.lockInGuess{value: value}(hash) returns (bool) { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(address(c).balance >= 2 ether);
        } else {
            // If it reverted, no assertion needed.
            assertTrue(true);
        }
