        uint256 balanceBefore = address(c).balance;
        vm.prank(player);
        try c.settle() {
            settledOk = true;
        } catch {
            settledOk = false;
        }
        uint256 balanceAfter = address(c).balance;

        assertTrue(!settledOk || balanceAfter >= balanceBefore);
    }
}
